local function esp_make(class_name, properties, children)
    local instance = Instance.new(class_name)

    for key, value in pairs(properties) do
        if key ~= "Parent" then
            instance[key] = value
        end
    end

    if children then
        for _, child in ipairs(children) do
            child.Parent = instance
        end
    end

    if esp_protect then
        pcall(esp_protect, instance)
    end

    instance.Parent = properties.Parent

    return instance
end

local function esp_decode(data)
    local native = (crypt and (crypt.base64decode or crypt.base64_decode)) or base64_decode or (base64 and base64.decode)

    if native then
        local ok, out = pcall(native, data)

        if ok and type(out) == "string" and #out > 0 then
            return out
        end
    end

    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}

    for i = 1, 64 do
        lookup[string.byte(alphabet, i)] = i - 1
    end

    local out = buffer.create(#data)
    local written, acc, bits = 0, 0, 0

    for i = 1, #data do
        local value = lookup[string.byte(data, i)]

        if value then
            acc = bit32.band(bit32.bor(bit32.lshift(acc, 6), value), 0xFFFFFF)
            bits += 6

            if bits >= 8 then
                bits -= 8
                buffer.writeu8(out, written, bit32.band(bit32.rshift(acc, bits), 255))
                written += 1
            end
        end
    end

    return buffer.readstring(out, 0, written)
end

