local function draw_visible(object, state)
    if object.visible ~= state then
        object.visible = state
        object.frame.Visible = state
    end
end

local function draw_color(object, color)
    object.frame.BackgroundColor3 = color

    if object.stroke then
        object.stroke.Color = color
    end
end

local function draw_thickness(object, thickness)
    object.thickness = thickness
    object.position = nil

    if object.stroke then
        object.stroke.Thickness = thickness
    end
end

local function draw_rect(object, position, size)
    if object.position == position and object.size == size then
        return
    end

    object.position, object.size = position, size

    local thickness = object.thickness

    object.frame.Position = from_offset(position.X + thickness, position.Y + thickness)
    object.frame.Size = from_offset(size.X - thickness * 2, size.Y - thickness * 2)
end

local function draw_segment(object, from, to)
    local middle = (from + to) / 2
    local delta = to - from

    object.frame.Position = from_offset(middle.X, middle.Y)
    object.frame.Rotation = math.deg(math.atan2(delta.Y, delta.X))
    object.frame.Size = from_offset(delta.Magnitude, object.thickness)
end

local function draw_place(object, position)
    if object.position ~= position then
        object.position = position
        object.frame.Position = from_offset(position.X, position.Y)
    end
end

local function esp_font(object, name)
    local info = esp.fonts[name]

    if not info then
        return
    end

    object.frame.TextSize = info.size
    object.frame.FontFace = info.font
end

