local function esp_sequence(key, transparency)
    local s = esp_settings() or {}
    local values = {}

    for i = 1, 3 do
        local value = s[key .. (transparency and "_alpha" or "_color") .. i]

        if value == nil then
            break
        end

        values[#values + 1] = value
    end

    if #values == 0 then
        return transparency and NumberSequence.new(0) or ColorSequence.new(Color3.new(1, 1, 1))
    end

    if #values == 1 then
        return transparency and NumberSequence.new(values[1]) or ColorSequence.new(values[1])
    end

    local points = {}

    for i, value in ipairs(values) do
        local position = (i - 1) / (#values - 1)

        points[i] = transparency and NumberSequenceKeypoint.new(position, value) or ColorSequenceKeypoint.new(position, value)
    end

    return transparency and NumberSequence.new(points) or ColorSequence.new(points)
end

