local function esp_refresh_tags()
    local s = esp_settings() or {}

    esp.tags["staring text"] = esp_tag(s.flag_staring_text_color1)
    esp.tags["health prefix"] = esp_tag(s.flag_health_text_color1)
    esp.tags["health text"] = esp_tag(s.flag_health_text_color2)
    esp.style = s.flag_style == "lower" and string.lower or string.upper

    local bridge = esp.style(string.sub(tostring(s.flag_bridge or ": "), 1, 30))

    bridge = string.gsub(bridge, "&", "&amp;")
    bridge = string.gsub(bridge, "'", "&apos;")
    bridge = string.gsub(bridge, "\"", "&quot;")
    bridge = string.gsub(bridge, ">", "&gt;")
    bridge = string.gsub(bridge, "<", "&lt;")

    esp.bridge = bridge
end

