    return (esp.tags[key] or "<font>") .. (raw and value or esp.style(tostring(value))) .. (newline and "</font>\n" or "</font>")
end

local function esp_healthbar_build(animate)
    local s = esp_settings() or {}
    local state = esp.healthbar
    local kind = s.healthbar_type or "gradient"
    local points = {}

    if kind == "rainbow" then
        for i = 0, 19 do
            local position = i / 19
            local hue = position

            if animate then
                hue += state.rainbow

                if hue > 1 then
                    hue -= 1
                end
            end

            points[#points + 1] = ColorSequenceKeypoint.new(position, Color3.fromHSV(hue, 0.5, 1))
        end

        return ColorSequence.new(points)
    elseif kind == "gradient" then
        local last = state.count - 1
        local alpha = state.elapsed / state.interval

        for i = 0, last do
            local index = #points + 1
            local color = state.colors[state.order[index]] or Color3.new(1, 1, 1)

            if animate then
                local previous = state.order[index - 1] or state.order[state.count]

                color = color:Lerp(state.colors[previous] or color, alpha)
            end

            points[index] = ColorSequenceKeypoint.new(i / last, color)
        end

        return ColorSequence.new(points)
    end

    return ColorSequence.new(state.colors[1] or Color3.new(0, 1, 0))
end

local function esp_healthbar_apply(sequence)
    esp.healthbar_sequence = sequence

    for _, gradient in ipairs(esp.gradients.healthbar) do
        gradient.Color = sequence
    end
end

local function esp_healthbar_options()
    local s = esp_settings() or {}
    local state = esp.healthbar
    local slices = clamp(floor(tonumber(s.healthbar_slices) or 1), 1, 6)

    table.clear(state.colors)
    table.clear(state.order)

    state.count = slices * 3

    for _, key in ipairs({"healthbar_color_start", "healthbar_color_middle", "healthbar_color_end"}) do
        for _ = 1, slices do
            table.insert(state.colors, s[key] or Color3.new(1, 1, 1))
        end
    end

    for i = 1, state.count do
        table.insert(state.order, i)
    end

    esp_healthbar_apply(esp_healthbar_build(s.healthbar_moving))
end

local function esp_invert(color, threshold)
    color = color or Color3.new(1, 1, 1)

    return threshold <= 1 and color or Color3.new(1 - color.R, 1 - color.G, 1 - color.B)
end

