local ESP_APPEARANCE_ROUTE = {Decal = "Clothes", ShirtGraphic = "Clothes", Shirt = "Clothes", Pants = "Clothes", MeshPart = "BasePart", UnionOperation = "BasePart", Part = "BasePart"}

local ESP_APPEARANCE_CACHE = {
    MeshPart = {"TextureID", "Color", "Material", "Transparency"},
    SpecialMesh = {"TextureId"},
    Part = {"Color", "Material", "Transparency"},
    UnionOperation = {"UsePartColor", "Color", "Material", "Transparency"},
    Shirt = {"ShirtTemplate"},
    Pants = {"PantsTemplate"},
    Decal = {"Texture"},
    ShirtGraphic = {"Graphic"},
}

local ESP_APPEARANCE_HANDLERS = {
    SpecialMesh = function(settings, target, cached)
        target.TextureId = settings.material and "" or cached.TextureId
    end,

    BasePart = function(settings, target, cached, class_name)
        if class_name == "MeshPart" then
            if settings.material and settings.material ~= Enum.Material.ForceField then
                target.TextureID = ""
            else
                target.TextureID = cached.TextureID
            end
        elseif class_name == "UnionOperation" then
            if settings.color ~= nil then
                target.UsePartColor = true
            else
                target.UsePartColor = cached.UsePartColor
            end
        end

        target.Color = settings.color or cached.Color

        if cached.Transparency <= 0.95 then
            target.Transparency = settings.transparency or cached.Transparency
        else
            target.Transparency = cached.Transparency
        end

        target.Material = settings.material or cached.Material
    end,

    Clothes = function(settings, target, cached, class_name)
        local strip = settings.clothes

        if not strip and settings.material then
            strip = settings.material ~= Enum.Material.ForceField
        end

        if class_name == "Decal" and settings.decals then
            strip = true
        end

        for property, value in pairs(cached) do
            target[property] = strip and "" or value
        end
    end,
}

local function esp_appearance_settings(record)
    if not record.character or esp_ally_hidden(record) then
        return
    end

    local s = esp_settings() or {}

    if not s.override_appearance then
        return
    end

    local disables = s.body_disables or {}
    local material = nil

    if s.material then
        pcall(function()
            material = Enum.Material[s.material_value or "ForceField"]
        end)
    end

    return {
        clothes = disables.clothing == true,
        decals = disables.decals == true,
        transparency = 1 - (tonumber(s.body_transparency) or 100) / 100,
        color = s.body_color and s.body_color_value or nil,
        material = material,
    }
end

local function esp_appearance_cache(record, character)
    local entry = {root = character, instances = {}, changing = false, connections = {}}

    local function track(instance)
        local class_name = instance.ClassName
        local properties = ESP_APPEARANCE_CACHE[class_name]

        if not properties then
            return
        end

        if instance.Name == "HumanoidRootPart" and instance:IsA("BasePart") then
            return
        end

        local saved = {}

        for _, property in ipairs(properties) do
            local ok, value = pcall(function()
                return instance[property]
            end)

            if ok then
                if property == "Transparency" and value == 0.875 then
                    value = 0
                end

                saved[property] = value
            end
        end

        entry.instances[class_name] = entry.instances[class_name] or {}
        entry.instances[class_name][instance] = saved
    end

    table.insert(entry.connections, character.DescendantAdded:Connect(track))

    for _, instance in ipairs(character:GetDescendants()) do
        track(instance)
    end

    record.appearance = entry

    return entry
end

local function esp_appearance_restore(entry)
    if not entry or not entry.modified then
        return
    end

    entry.changing = true
    entry.modified = false

    for _, objects in pairs(entry.instances) do
        for object, saved in pairs(objects) do
            if object.Parent then
                for property, value in pairs(saved) do
                    pcall(function()
                        object[property] = value
                    end)
                end
            end
        end
    end

    entry.changing = false
end

local function esp_appearance_drop(record)
    local entry = record.appearance

    if not entry then
        return
    end

    esp_appearance_restore(entry)

    for _, connection in ipairs(entry.connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end

    record.appearance = nil
end

local function esp_appearance_change(record)
    local settings = esp_appearance_settings(record)
    local character = record.character
    local entry = record.appearance

    if entry and entry.root ~= character then
        esp_appearance_drop(record)
        entry = nil
    end

    if not settings and not entry then
        return
    end

    if not character then
        return
    end

    entry = entry or esp_appearance_cache(record, character)

    if entry.changing then
        entry.again = true
        return
    end

    if not settings then
        return esp_appearance_restore(entry)
    end

    entry.changing = true
    entry.modified = true

    for class_name, objects in pairs(entry.instances) do
        local handler = ESP_APPEARANCE_HANDLERS[ESP_APPEARANCE_ROUTE[class_name]] or ESP_APPEARANCE_HANDLERS[class_name]

        if handler then
            for object, saved in pairs(objects) do
                if object.Parent then
                    pcall(handler, settings, object, saved, class_name)
                else
                    objects[object] = nil
                end
            end
        end
    end

    entry.changing = false

    if entry.again then
        entry.again = false
        esp_appearance_change(record)
    end
end

local function esp_effects_destroy(record, kind)
    local current = record.effects[kind]

    for _, instance in ipairs(current) do
        pcall(function()
            instance:Destroy()
        end)
    end

    table.clear(current)
end

local function esp_effects_update(record, kind)
    local s = esp_settings() or {}
    local prefix = "effects_" .. kind
    local first = s[prefix .. "_color1"] or Color3.new(1, 1, 1)
    local middle = s[prefix .. "_color2"] or Color3.new(1, 1, 1)
    local last = s[prefix .. "_color3"] or Color3.new(1, 1, 1)
    local sequence = ColorSequence.new({
        ColorSequenceKeypoint.new(0, first),
        ColorSequenceKeypoint.new(0.5, middle),
        ColorSequenceKeypoint.new(1, last),
    })

    for _, instance in ipairs(record.effects[kind]) do
        local list = instance:GetDescendants()

        table.insert(list, instance)

        for _, object in ipairs(list) do
            local class_name = object.ClassName

            if class_name == "Beam" or class_name == "ParticleEmitter" then
                object.Color = sequence
            elseif string.find(class_name, "Light", 1, true) then
                object.Color = middle
            end
        end
    end
end

local function esp_effects_create(record, character, selected, kind)
    esp_effects_destroy(record, kind)

    local storage = esp.effects[kind]

    for name, enabled in pairs(selected) do
        local template = enabled and storage[name]

        if template then
            local copy = template:Clone()

            for _, holder in ipairs(copy:GetChildren()) do
                local target = character:FindFirstChild(holder.Name)

                if target then
                    local clone = holder:Clone()

                    for _, descendant in ipairs(clone:GetDescendants()) do
                        descendant.Name = ""
                        descendant.Archivable = false

                        if descendant.ClassName == "ParticleEmitter" and descendant.SpreadAngle == Vector2.zero then
                            descendant.SpreadAngle = vec2(0.001, 0.001)
                        end
                    end

                    for _, child in ipairs(clone:GetChildren()) do
                        child.Parent = target
                        table.insert(record.effects[kind], child)
                    end

                    clone:Destroy()
                end
            end

            copy:Destroy()
        end
    end

    esp_effects_update(record, kind)
end

local function esp_effects_refresh(record)
    local s = esp_settings() or {}

    for _, kind in ipairs({"aura", "particle"}) do
        if esp_ally_hidden(record) then
            esp_effects_destroy(record, kind)
        elseif record.character and s["effects_" .. kind] then
            pcall(esp_effects_create, record, record.character, s["effects_" .. kind .. "_value"] or {}, kind)
        else
            esp_effects_destroy(record, kind)
        end
    end
end

local function esp_display_name(player, s)
    if type(s.name_spoof) == "string" and s.name_spoof ~= "" then
        return s.name_spoof
    end

    local key = s.name_type == "DisplayName" and "DisplayName" or "Name"

    return player[key]
end

local function esp_style_record(record, s)
    local font = s.font or "monocraft"

    for _, key in ipairs({"name", "weapon", "distance"}) do
        local gradient = record.gradients[key]

        gradient.Color = esp_sequence(key)
        gradient.Rotation = tonumber(s[key .. "_rotation"]) or 0
    end

    local box = record.gradients.box

    box.Color = esp_sequence("box")
    box.Rotation = tonumber(s.box_rotation) or 0

    record.texts[1].frame.Text = esp_display_name(record.player, s)

    for _, text in ipairs(record.texts) do
        esp_font(text, font)
    end

    record.text_height = ESP_FLAG_HEIGHT[font] or (esp.fonts[font] or esp.fonts.ubuntu).size

    esp_font(record.texts[1], s.name_font or "default")

    local first = s.skeleton_color1 or Color3.new(1, 1, 1)
    local middle = s.skeleton_color2 or Color3.new(1, 1, 1)
    local last = s.skeleton_color3 or Color3.new(1, 1, 1)
    local bones = {ColorSequence.new(middle, last), ColorSequence.new(first, middle), ColorSequence.new(first)}
    local thickness = tonumber(s.skeleton_thickness) or 1

    for index, line in ipairs(record.lines) do
        local outline = index > 13

        line.thickness = thickness + (outline and 2 or 0)

        if not outline then
            line.gradient.Color = index == 13 and ColorSequence.new(last) or bones[((index - 1) % 3) + 1]
        end
    end

    local image = esp.fill_images[s.fill_image or "default"] or esp.fill_images.default
    local fill_frame = record.fill.frame

    fill_frame.Image = image.image
    fill_frame.BackgroundTransparency = image.image ~= "" and 1 or 0
    record.fill_scale = image.size

    local fill = record.gradients.fill

    fill.Color = esp_sequence("fill")
    fill.Transparency = esp_sequence("fill", true)
    fill.Rotation = tonumber(s.fill_rotation) or 0

    local flag_font = s.flag_font or "smallest pixel"

    record.flag_offset = ESP_FLAG_OFFSET[flag_font] or Vector2.zero
    esp_font(record.texts[4], flag_font)

    local character = record.character

    if character and character.Parent then
        if esp_ally_hidden(record) then
            pcall(function()
                character.Parent = workspace
            end)
        elseif not record.preview then
            pcall(function()
                character.Parent = esp.chams_model
            end)
        end

        esp_appearance_change(record)
    end
end

local function esp_hide(record)
    if record.hidden then
        return
    end

    record.hidden = true

    for _, object in ipairs(record.drawings) do
        draw_visible(object, false)
    end
end

local function esp_hide_skeleton(record)
    if record.skeleton_hidden then
        return
    end

    record.skeleton_hidden = true

    for _, line in ipairs(record.lines) do
        draw_visible(line, false)
    end
end

local function esp_drop_character(record)
    for _, connection in ipairs(record.character_connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end

    table.clear(record.character_connections)
end

local function esp_stare(record, direction)
    local dueler = record.dueler
    local fighter = dueler and rawget(dueler, "ClientFighter")
    local entity = fighter and rawget(fighter, "Entity")
    local joints = entity and rawget(entity, "Joints")
    local spring = (joints and rawget(joints, "_camera_rotation_spring")) or (fighter and rawget(fighter, "_camera_rotation_spring"))
    local target = spring and rawget(spring, "_target")

    if typeof(target) ~= "Vector2" then
        target = Vector2.zero
    end

    local facing = (CFrame.Angles(0, target.Y, 0) * CFrame.Angles(target.X, 0, 0)).LookVector

    return facing:Dot(direction.Unit) > 0.5
end

local function esp_on_character(record, character)
    record.character = character
    record.lerp = 0
    esp_drop_character(record)
    table.clear(record.parts)
    table.clear(record.corners)

    local root = character:WaitForChild("HumanoidRootPart", huge)
    local humanoid = character:WaitForChild("Humanoid", huge)

    if record.character ~= character or esp.running[record.player] ~= record then
        return
    end

    table.insert(record.character_connections, humanoid:GetPropertyChangedSignal("Health"):Connect(function()
        record.health = humanoid.Health
    end))

    table.insert(record.character_connections, humanoid:GetPropertyChangedSignal("MaxHealth"):Connect(function()
        record.max_health = humanoid.MaxHealth
    end))

    record.health, record.max_health = humanoid.Health, humanoid.MaxHealth
    record.root, record.humanoid = root, humanoid

    for _, name in ipairs(ESP_SKELETON_PARTS) do
        local part = character:WaitForChild(name, huge)

        if record.character ~= character then
            return
        end

        record.parts[name] = part
        record.corners[part] = esp_part_corners(part)
    end

    task.wait()

    if record.character ~= character or esp.running[record.player] ~= record or esp_ally_hidden(record) then
        return
    end

    pcall(function()
        character.Parent = esp.chams_model
    end)

    esp_appearance_change(record)
    esp_effects_refresh(record)
end

local function esp_release_drawings(record)
    for kind, gradient in pairs(record.gradients) do
        local list = esp.gradients[kind]
        local index = list and table.find(list, gradient)

        if index then
            table.remove(list, index)
        end
    end

    for _, object in ipairs(record.drawings) do
        pcall(function()
            object.frame:Destroy()
        end)
    end
end

local function esp_remove(player)
    local record = esp.running[player]

    if not record then
        return
    end

    esp.running[player] = nil

    for _, connection in ipairs(record.connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end

    esp_drop_character(record)

    esp_release_drawings(record)
    esp_effects_destroy(record, "aura")
    esp_effects_destroy(record, "particle")
    esp_appearance_drop(record)

    local character = record.character

    if character and character.Parent == esp.chams_model then
        pcall(function()
            character.Parent = workspace
        end)
    end
end

esp.bridge_event = Instance.new("BindableEvent")

local function esp_build_record(player, dueler)
    local s = esp_settings() or {}
    local record = {
        player = player,
        dueler = dueler,
        connections = {},
        character_connections = {},
        drawings = {},
        lines = {},
        texts = {},
        squares = {},
        gradients = {},
        effects = {aura = {}, particle = {}},
        parts = {},
        corners = {},
        health = 0,
        max_health = 150,
        lerp = 0,
        hidden = false,
        skeleton_hidden = false,
        text_height = 12,
        flag_offset = Vector2.zero,
    }

    for index = 1, 26 do
        local outline = index > 13
        local line = draw_line(record)

        line.frame.BackgroundColor3 = outline and Color3.new() or Color3.new(1, 1, 1)
        line.frame.ZIndex = outline and 0 or 2
        record.lines[index] = line
    end

    for index = 1, 13 do
        local gradient = Instance.new("UIGradient")

        gradient.Parent = record.lines[index].frame
        record.lines[index].gradient = gradient
    end

    for index = 1, 4 do
        record.texts[index] = draw_text(record)
    end

    for index = 1, 4 do
        record.squares[index] = draw_square(record)
    end

    record.fill = draw_image(record)

    local outline, box, bar, back = record.squares[1], record.squares[2], record.squares[3], record.squares[4]

    draw_thickness(outline, 3)
    box.frame.ZIndex = 2
    draw_color(box, Color3.new(1, 1, 1))
    bar.frame.ZIndex = 2
    draw_color(bar, Color3.new(1, 1, 1))
    bar.frame.BackgroundTransparency = 0
    bar.frame.AnchorPoint = vec2(0, 1)
    back.frame.BackgroundTransparency = 0
    back.frame.AnchorPoint = vec2(0, 1)

    record.texts[2].frame.Text = "none"
    record.texts[4].frame.RichText = true
    record.texts[4].frame.TextXAlignment = Enum.TextXAlignment.Left

    for index, key in ipairs({"name", "weapon", "distance"}) do
        local frame = record.texts[index].frame
        local gradient = Instance.new("UIGradient")

        frame.AnchorPoint = vec2(0.5, 0)
        frame.AutomaticSize = Enum.AutomaticSize.XY
        gradient.Parent = frame
        esp_register(record, key, gradient)
    end

    record.texts[1].frame.AnchorPoint = vec2(0.5, 1)

    local fill_frame = record.fill.frame

    fill_frame.BackgroundColor3 = Color3.new(1, 1, 1)
    fill_frame.AnchorPoint = vec2(0.5, 0.5)

    local fill_gradient = Instance.new("UIGradient")

    fill_gradient.Parent = fill_frame
    esp_register(record, "fill", fill_gradient)

    local box_gradient = Instance.new("UIGradient")

    box_gradient.Parent = box.stroke
    esp_register(record, "box", box_gradient)

    local bar_gradient = Instance.new("UIGradient")

    bar_gradient.Color = esp.healthbar_sequence
    bar_gradient.Rotation = 90
    bar_gradient.Parent = bar.stroke
    esp_register(record, "healthbar", bar_gradient)

    esp_style_record(record, s)

    return record
end

local function esp_add(player, dueler)
    if not player or player == local_player or esp.running[player] then
        return
    end

    local record = esp_build_record(player, dueler)

    esp.running[player] = record

    local fighter = dueler and rawget(dueler, "ClientFighter")

    if fighter then
        local changed = rawget(fighter, "EquippedItemChanged")
        local function relay(item)
            local name = type(item) == "table" and rawget(item, "Name")

            esp.bridge_event:Fire("weapon", player, type(name) == "string" and name or false)
        end

        if changed then
            pcall(function()
                table.insert(record.connections, changed:Connect(relay))
            end)
        end

        task.spawn(relay, rawget(fighter, "EquippedItem"))
    end

    table.insert(record.connections, player.CharacterAdded:Connect(function(character)
        esp_on_character(record, character)
    end))

    table.insert(record.connections, player.CharacterRemoving:Connect(function(character)
        if record.character == character then
            record.character, record.root, record.humanoid, record.health = nil, nil, nil, 0
            record.texts[2].frame.Text = "none"
            table.clear(record.parts)
            table.clear(record.corners)
            esp_drop_character(record)
        end
    end))

    if player.Character then
        task.spawn(esp_on_character, record, player.Character)
    end
end

local function esp_bounds(record, position, s, camera_cframe)
    if s.bounds_type ~= "fixed" then
        local _, visible = esp_project(position)

        if not visible then
            return
        end

        local min_x, min_y, max_x, max_y = huge, huge, -huge, -huge
        local any = false
        local projector, camera = esp_projector, esp.camera

        for part, corners in pairs(record.corners) do
            local part_cframe = part.CFrame

            for index = 1, 8 do
                local world = part_cframe * corners[index]
                local point, on_screen

                if projector then
                    point, on_screen = projector(world)
                else
                    point, on_screen = camera:WorldToViewportPoint(world)
                end

                if on_screen then
                    any = true

                    local x, y = point.X, point.Y

                    min_x, min_y = min(min_x, x), min(min_y, y)
                    max_x, max_y = max(max_x, x), max(max_y, y)
                end
            end
        end

        if not any then
            return
        end

        local size = esp_floor(vec2(max(10, max_x - min_x), max(10, max_y - min_y)))

        return size, esp_floor(vec2(min_x + size.X / 2, min_y))
    end

    local up = camera_cframe.UpVector
    local top, visible = esp_project(position + up * 2.5)

    if not visible then
        return
    end

    if (position - camera_cframe.Position).Magnitude > 600 then
        local info = esp.fonts[s.font or "monocraft"] or esp.fonts.ubuntu

        return vec2(5, info.size - 2), esp_floor(top)
    end

    local bottom, bottom_visible = esp_project(position - up * 3.5)

    if not bottom_visible then
        return
    end

    local height = max(10, abs(bottom.Y - top.Y))
    local scale = (tonumber(s.bounds_width_scale) or 100) / 100

    return esp_floor(vec2(height * scale, height)), esp_floor(top)
end

local function esp_skeleton(record, s)
    if not s.skeleton then
        return esp_hide_skeleton(record)
    end

    local points = {}
    local count = 0

    for name, part in pairs(record.parts) do
        count += 1

        local position = part.Position

        if name == "UpperTorso" then
            position += Vector3.new(0, part.Size.Y / 3, 0)
        end

        points[name] = esp_project(position)
    end

    if count ~= #ESP_SKELETON_PARTS then
        return esp_hide_skeleton(record)
    end

    record.skeleton_hidden = false

    for index, bone in ipairs(ESP_BONES) do
        local line, outline = record.lines[index], record.lines[index + 13]
        local first, second = points[bone[1]], points[bone[2]]
        local unit = (first - second).Unit

        draw_segment(line, first + unit, second - unit)

        if s.skeleton_outline then
            local wide = unit * 2

            draw_segment(outline, first + wide, second - wide)
            draw_visible(outline, true)
        else
            draw_visible(outline, false)
        end

        draw_visible(line, true)
    end
end

local function esp_step(record, s, camera_cframe)
    local any = s.healthbar or s.name or s.distance or s.weapon or s.box or s.fill or s.skeleton or s.flag_health_text or s.flag_staring_text
    local root = record.root

    if not any or not root or not root.Parent or esp_ally_hidden(record) or record.health <= 0 then
        return esp_hide(record)
    end

    local position = root.Position
    local size, top = esp_bounds(record, position, s, camera_cframe)

    if not size then
        return esp_hide(record)
    end

    record.hidden = false

    esp_skeleton(record, s)

    local outline, box, bar, back = record.squares[1], record.squares[2], record.squares[3], record.squares[4]
    local name, weapon, distance, flags = record.texts[1], record.texts[2], record.texts[3], record.texts[4]

    if s.box then
        local origin = top - vec2(size.X / 2, 0)

        draw_rect(box, origin, size)
        draw_rect(outline, origin - vec2(1, 1), size + vec2(2, 2))
        draw_visible(box, true)
        draw_visible(outline, true)
    else
        draw_visible(box, false)
        draw_visible(outline, false)
    end

    if s.name then
        draw_place(name, top - vec2(0, 2))
        draw_visible(name, true)
    else
        draw_visible(name, false)
    end

    local fill = record.fill

    if s.fill then
        local center = top + vec2(0, size.Y / 2)
        local fill_size = record.fill_scale and size * record.fill_scale or size

        if fill.position ~= center or fill.size ~= fill_size then
            fill.position, fill.size = center, fill_size
            fill.frame.Size = from_offset(fill_size.X, fill_size.Y)
            fill.frame.Position = from_offset(center.X, center.Y)
        end

        draw_visible(fill, true)
    else
        draw_visible(fill, false)
    end

    local text = ""

    if s.flag_health_text then
        local prefix = ESP_HEALTH_PREFIX[s.flag_prefix or "full"]
        local head = prefix and (esp_rich("health prefix", prefix) .. esp_rich("health prefix", esp.bridge, nil, true)) or ""

        text = text .. head .. esp_rich("health text", floor(record.health), true)
    end

    if s.flag_staring_text and esp_stare(record, camera_cframe.Position - position) then
        text = text .. esp_rich("staring text", "staring")
    end

    if flags.text ~= text then
        flags.text = text
        flags.frame.Text = text
    end

    draw_place(flags, top + vec2(size.X / 2 + 2, 0) + record.flag_offset)
    draw_visible(flags, true)

    if s.weapon then
        draw_place(weapon, top + vec2(0, size.Y + 1))
        draw_visible(weapon, true)
    else
        draw_visible(weapon, false)
    end

    if s.distance then
        local offset = weapon.visible and (size.Y + record.text_height) or size.Y
        local label = "[" .. round((camera_cframe.Position - position).Magnitude) .. "]"

        draw_place(distance, top + vec2(0, offset + 2))

        if distance.text ~= label then
            distance.text = label
            distance.frame.Text = label
        end

        draw_visible(distance, true)
    else
        draw_visible(distance, false)
    end

    if s.healthbar then
        local shifted = top - vec2(0, 1)
        local tall = size + vec2(0, 2)
        local base = shifted - vec2(tall.X / 2 + 6, -tall.Y + 1) - vec2(-1, 2)
        local ratio = record.health / max(record.max_health, 1)

        record.lerp = record.lerp + (ratio - record.lerp) * (tonumber(s.healthbar_health_lerp) or 0.05)

        local bar_size = vec2(2, max(2, (tall.Y - 2) * record.lerp))

        draw_rect(bar, base, bar_size)
        record.gradients.healthbar.Offset = vec2(0, record.lerp - 1)

        if s.healthbar_resize ~= false then
            draw_rect(back, base - vec2(1, -1), vec2(4, bar_size.Y + 2))
        else
            draw_rect(back, base - vec2(1, -1), vec2(4, tall.Y))
        end

        draw_visible(back, true)
        draw_visible(bar, true)
    else
        draw_visible(back, false)
        draw_visible(bar, false)
    end
end

local ESP_PREVIEW_RATE = 0.1

local function esp_preview_project(position)
    local preview = esp_preview
    local relative = preview.view:PointToObjectSpace(position)
    local depth = -relative.Z

    if depth <= 0.05 then
        return vec2(), false
    end

    local size = preview.size

    return vec2((relative.X / (depth * preview.tan * preview.aspect) * 0.5 + 0.5) * size.X, (0.5 - relative.Y / (depth * preview.tan) * 0.5) * size.Y), true
end

local function esp_preview_render()
    local preview = esp_preview

    if not preview then return end

    local container, camera = preview.container, preview.camera

    if not container.Parent or not camera.Parent then return end

    local size = container.AbsoluteSize

    if size.X < 2 or size.Y < 2 then return end

    local record = preview.record

    preview.size = size
    preview.view = camera.CFrame
    preview.tan = math.tan(math.rad(camera.FieldOfView) / 2)
    preview.aspect = size.X / size.Y
    preview.at = tick()
    record.lerp = record.health / max(record.max_health, 1)

    esp_projector = esp_preview_project

    local ok = pcall(esp_step, record, esp_settings() or {}, camera.CFrame)

    esp_projector = nil

    if not ok then
        esp_hide(record)
    end

    local source, highlight = esp.highlight, preview.highlight

    highlight.Enabled = source.Enabled
    highlight.FillColor = source.FillColor
    highlight.FillTransparency = source.FillTransparency
    highlight.OutlineColor = source.OutlineColor
    highlight.OutlineTransparency = source.OutlineTransparency
end

local function esp_preview_restyle()
    local preview = esp_preview

    if not preview then return end

    pcall(esp_style_record, preview.record, esp_settings() or {})
    pcall(esp_appearance_change, preview.record)

    esp_preview_render()
end

local function esp_preview_detach()
    local preview = esp_preview

    if not preview then return end

    esp_preview = nil

    esp_release_drawings(preview.record)
    esp_appearance_drop(preview.record)

    pcall(function()
        preview.highlight:Destroy()
    end)
end

local function esp_preview_attach(container, model, camera, weapon)
    esp_preview_detach()

    if typeof(container) ~= "Instance" or typeof(model) ~= "Instance" or typeof(camera) ~= "Instance" then
        return false
    end

    local record = esp_build_record(local_player, nil)

    record.preview = true

    for _, object in ipairs(record.drawings) do
        object.frame.Parent = container
    end

    for _, name in ipairs(ESP_SKELETON_PARTS) do
        local part = model:FindFirstChild(name)

        if part and part:IsA("BasePart") then
            record.parts[name] = part
            record.corners[part] = esp_part_corners(part)
        end
    end

    record.character = model
    record.root = model:FindFirstChild("HumanoidRootPart")
    record.humanoid = model:FindFirstChildOfClass("Humanoid")
    record.health, record.max_health = 75, 100
    record.texts[2].frame.Text = type(weapon) == "string" and weapon ~= "" and weapon or "none"

    local highlight = Instance.new("Highlight")

    highlight.Name = "\0"
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.Enabled = false
    highlight.Adornee = model
    highlight.Parent = model

    esp_preview = {record = record, container = container, model = model, camera = camera, highlight = highlight, at = 0}

    esp_preview_restyle()

    return true
end

getgenv().SleepyESPPreview = {
    attach = esp_preview_attach,
    detach = esp_preview_detach,
    render = esp_preview_render,
    restyle = esp_preview_restyle,
}

local esp_item_library = nil

pcall(function()
    esp_item_library = require(replicated_storage:WaitForChild("Modules", 10):WaitForChild("ItemLibrary", 10))
end)

local function esp_world_add(item_name, target)
    local s = esp_settings() or {}

    if not (s.world_image or s.world_name or s.world_distance) then
        return
    end

    if not item_name or not target or not target.Parent or not (s.world_whitelist or {})[item_name] then
        return
    end

    local view_models = esp_item_library and esp_item_library.ViewModels
    local info = view_models and view_models[item_name]
    local image = info and (info.ImageHighResolution or info.Image)

    if not image or image == "" then
        return
    end

    local face = esp.fonts[s.world_font or "monocraft"] or esp.fonts.ubuntu
    local fades = {}
    local root_frame = esp_make("Frame", {BackgroundTransparency = 1, BorderSizePixel = 0, AnchorPoint = vec2(0.5, 0.5), Size = UDim2.new(), Visible = false, Parent = world_gui})
    local name_label = esp_make("TextLabel", {Text = item_name, FontFace = face.font, TextSize = face.size, BackgroundTransparency = 1, BorderSizePixel = 0, AnchorPoint = vec2(0.5, 1), AutomaticSize = Enum.AutomaticSize.XY, Position = UDim2.new(0.5, 0, 0, -2), TextColor3 = s.world_name_color or Color3.new(1, 1, 1), Parent = root_frame})
    local distance_label = esp_make("TextLabel", {Text = "0s", FontFace = face.font, TextSize = face.size, BackgroundTransparency = 1, BorderSizePixel = 0, AnchorPoint = vec2(0.5, 0), AutomaticSize = Enum.AutomaticSize.XY, Position = UDim2.fromScale(0.5, 1), TextColor3 = s.world_name_color or Color3.new(1, 1, 1), Parent = root_frame})
    local clip = esp_make("Frame", {ClipsDescendants = true, Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, Parent = root_frame})
    local icon = esp_make("ImageLabel", {Image = image, BackgroundTransparency = 1, BorderSizePixel = 0, Position = UDim2.fromScale(0.5, 0.5), AnchorPoint = vec2(0.5, 0.5), Size = UDim2.fromScale(3, 3), Parent = clip})
    local distance_stroke = esp_make("UIStroke", {LineJoinMode = Enum.LineJoinMode.Miter, Parent = distance_label})
    local name_stroke = esp_make("UIStroke", {LineJoinMode = Enum.LineJoinMode.Miter, Parent = name_label})

    fades[icon] = "ImageTransparency"
    fades[name_label] = "TextTransparency"
    fades[distance_label] = "TextTransparency"
    fades[distance_stroke] = "Transparency"
    fades[name_stroke] = "Transparency"

    local hidden = false
    local target_position = target:GetPivot().Position
    local elapsed = nil
    local scale = 0

    local connection = nil

    local function hide()
        if not hidden then
            hidden = true
            root_frame.Visible = false
        end
    end

    local function finish()
        if elapsed then
            return
        end

        elapsed = 0

        task.delay(max(tonumber((esp_settings() or {}).world_fade) or 0.2, 0.001), function()
            if connection then
                connection:Disconnect()
            end

            root_frame:Destroy()
        end)
    end

    local function step(delta)
        local settings = esp_settings() or {}

        if not (settings.world_whitelist or {})[item_name] then
            return hide()
        end

        if not elapsed and not target.Parent then
            finish()
        end

        if not elapsed then
            pcall(function()
                target_position = target:GetPivot().Position
            end)
        end

        local camera = workspace.CurrentCamera

        if not camera then
            return hide()
        end

        local point, on_screen = camera:WorldToViewportPoint(target_position)

        if not on_screen then
            return hide()
        end

        hidden = false
        root_frame.Visible = true

        local font = esp.fonts[settings.world_font or "monocraft"] or esp.fonts.ubuntu

        distance_label.FontFace = font.font
        distance_label.TextSize = font.size
        name_label.FontFace = font.font
        name_label.TextSize = font.size

        local studs = floor((camera.CFrame.Position - target_position).Magnitude)

        if settings.world_distance then
            distance_label.Text = studs .. "s"
            distance_label.Visible = true
            distance_label.TextColor3 = settings.world_distance_color or Color3.new(1, 1, 1)
        else
            distance_label.Visible = false
        end

        name_label.Visible = settings.world_name == true
        name_label.TextColor3 = settings.world_name_color or Color3.new(1, 1, 1)
        root_frame.Position = from_offset(point.X, point.Y)
        root_frame.ZIndex = -studs

        local fade_time = max(tonumber(settings.world_fade) or 0.2, 0.001)

        if elapsed then
            elapsed += delta

            local alpha = clamp(elapsed / fade_time, 0, 1)

            for object, property in pairs(fades) do
                object[property] = alpha
            end
        end

        if not settings.world_image then
            root_frame.Size = from_offset(0, 0)
            scale = 0

            return
        end

        local base = 50 * (tonumber(settings.world_object_scale) or 100) / 100
        local amount, wanted

        if settings.world_fade_mode ~= "fade" and elapsed then
            amount = 1
            wanted = base * (1 - clamp(elapsed / fade_time, 0, 1))
        else
            amount = tonumber(settings.world_lerp_speed) or 0.1
            wanted = base
        end

        if scale == wanted then
            return
        end

        scale = scale + (wanted - scale) * amount
        root_frame.Size = from_offset(scale, scale)
    end

    connection = run_service.RenderStepped:Connect(LPH_NO_VIRTUALIZE(function(delta)
        local ok = pcall(step, delta)

        if not ok then
            hide()
        end
    end))

    target.Destroying:Connect(finish)
end

local esp_spectate = nil

pcall(function()
    esp_spectate = require(local_player:WaitForChild("PlayerScripts", 10):WaitForChild("Controllers", 10):WaitForChild("SpectateController", 10))
end)

local esp_leaving = setmetatable({}, {__mode = "k"})

local function esp_round_only()
    local s = esp_settings()

    return not s or s.round_only ~= false
end

local function esp_add_everyone()
    if esp_round_only() then
        return
    end

    for _, player in ipairs(players_service:GetPlayers()) do
        esp_add(player, nil)
    end
end

local function esp_set_subject(subject)
    for _, connection in ipairs(esp.subject_connections) do
        pcall(function()
            connection:Disconnect()
        end)
    end

    table.clear(esp.subject_connections)

    for player in pairs(esp.running) do
        esp_remove(player)
    end

    if not subject then
        esp_add_everyone()

        return
    end

    pcall(function()
        table.insert(esp.subject_connections, subject.DuelerAdded:Connect(function(dueler)
            if dueler and dueler.Player ~= local_player then
                esp.bridge_event:Fire("add", function()
                    return dueler.Player, dueler
                end)
            end
        end))
    end)

    pcall(function()
        table.insert(esp.subject_connections, subject.DuelerRemoved:Connect(function(dueler)
            esp.bridge_event:Fire("remove", dueler and dueler.Player)
        end))
    end)

    local duelers = rawget(subject, "_duelers_by_player")

    if type(duelers) == "table" then
        for _, dueler in pairs(duelers) do
            if dueler.Player ~= local_player then
                esp_add(dueler.Player, dueler)
            end
        end
    end

    esp_add_everyone()
end

local esp_refresh_task = nil

local function esp_refresh_all()
    if esp_refresh_task then
        pcall(task.cancel, esp_refresh_task)
    end

    esp_refresh_task = task.delay(1 / 240, function()
        esp_refresh_task = nil

        local s = esp_settings() or {}

        esp_refresh_tags()

        for _, record in pairs(esp.running) do
            pcall(esp_style_record, record, s)
        end

        esp_preview_restyle()
    end)
end

esp.bridge_event.Event:Connect(function(kind, first, second)
    if kind == "add" then
        local ok, player, dueler = pcall(first)

        if ok then
            local record = esp.running[player]

            if record and dueler and not record.dueler then
                esp_remove(player)
            end

            esp_add(player, dueler)
        end
    elseif kind == "remove" then
        esp_remove(first)

        if not esp_round_only() and typeof(first) == "Instance" and first.Parent == players_service and not esp_leaving[first] then
            esp_add(first, nil)
        end
    elseif kind == "leave" then
        esp_remove(first)
    elseif kind == "subject" then
        esp_set_subject(esp_spectate and esp_spectate.CurrentDuelSubject)
    elseif kind == "weapon" then
        local record = esp.running[first]

        if record then
            record.texts[2].frame.Text = second or "none"
        end
    end
end)

players_service.PlayerAdded:Connect(function(player)
    if not esp_round_only() then
        esp.bridge_event:Fire("add", function()
            return player, nil
        end)
    end
end)

players_service.PlayerRemoving:Connect(function(player)
    esp_leaving[player] = true
    esp.bridge_event:Fire("leave", player)
end)

getgenv().SleepyESPSignal = function(kind)
    if kind == "chams" then
        esp_chams_apply()
    elseif kind == "effects" then
        for _, record in pairs(esp.running) do
            esp_effects_refresh(record)
        end
    elseif kind == "effects_color" then
        for _, record in pairs(esp.running) do
            esp_effects_update(record, "aura")
            esp_effects_update(record, "particle")
        end
    elseif kind == "healthbar" then
        esp_healthbar_options()
    elseif kind == "subject" then
        esp.bridge_event:Fire("subject")
    else
        esp_refresh_all()
    end
end

run_service.RenderStepped:Connect(LPH_NO_VIRTUALIZE(function(delta)
    local s = esp_settings()
    local camera = workspace.CurrentCamera

    if not s or not camera then
        for _, record in pairs(esp.running) do
            esp_hide(record)
        end

        return
    end

    esp.camera = camera

    local now = tick()

    for _, kind in ipairs({"box", "fill"}) do
        if s[kind .. "_moving"] then
            local rotation = (now * 360 * (tonumber(s[kind .. "_rotation_speed"]) or 0.1)) % 360

            for _, gradient in ipairs(esp.gradients[kind]) do
                gradient.Rotation = rotation
            end
        end
    end

    local state = esp.healthbar

    if s.healthbar_moving and s.healthbar then
        local step = delta * state.count / 3 * (tonumber(s.healthbar_speed) or 1)

        state.rainbow += step
        state.elapsed += step

        if state.rainbow > 1 then
            state.rainbow = 0
        end

        if state.elapsed > state.interval then
            state.elapsed = 0

            local previous = table.clone(state.order)

            state.order[1] = previous[state.count]

            for index = 2, state.count do
                state.order[index] = previous[index - 1]
            end
        end

        esp_healthbar_apply(esp_healthbar_build(true))
    end

    local highlight = esp.highlight
    local pulse = esp.pulse

    if s.chams_settings and s.chams_settings.pulse then
        local reference = tonumber(s.chams_alpha_fill) or 2

        if pulse.value < -1 or pulse.value > 3 then
            pulse.direction = not pulse.direction
            pulse.value = clamp(pulse.value, -1, 3)
        end

        pulse.value += pulse.direction and -delta or delta
        highlight.FillColor = esp_invert(s.chams_color2, pulse.value)
        highlight.FillTransparency = min(pulse.value, reference)
    elseif pulse.direction ~= nil then
        pulse.direction = nil
        highlight.FillTransparency = tonumber(s.chams_alpha_fill) or 2
        highlight.FillColor = esp_invert(s.chams_color2, highlight.FillTransparency)
    end

    local camera_cframe = camera.CFrame

    for _, record in pairs(esp.running) do
        local ok = pcall(esp_step, record, s, camera_cframe)

        if not ok then
            esp_hide(record)
        end
    end

    if esp_preview and now - esp_preview.at >= ESP_PREVIEW_RATE then
        esp_preview_render()
    end
end))

players_service.PlayerRemoving:Connect(function(player)
    esp_remove(player)
end)

collection_service:GetInstanceAddedSignal("SubspaceTripmine"):Connect(function(instance)
    pcall(esp_world_add, "Subspace Tripmine", instance)
end)

task.spawn(function()
    local throwables = nil
    local cosmetics = nil

    pcall(function()
        throwables = local_player:WaitForChild("PlayerScripts", 10):WaitForChild("Assets", 10):WaitForChild("Throwables", 10)
    end)

    pcall(function()
        cosmetics = require(replicated_storage:WaitForChild("Modules", 10):WaitForChild("CosmeticLibrary", 10))
    end)

    if not throwables then
        return
    end

    workspace.ChildAdded:Connect(function(child)
        if not child:IsA("Model") or not throwables:FindFirstChild(child.Name) then
            return
        end

        local cosmetic = cosmetics and cosmetics.Cosmetics and cosmetics.Cosmetics[child.Name]
        local item_name = type(cosmetic) == "table" and cosmetic.ItemName or child.Name

        task.defer(function()
            pcall(esp_world_add, item_name, child)
        end)
    end)
end)

task.spawn(function()
    local raw = esp_decode(ESP_ASSETS.bundle)
    local roots = nil

    ESP_ASSETS.bundle = nil

    local ok, result = pcall(function()
        return game:GetService("SerializationService"):DeserializeInstancesAsync(buffer.fromstring(raw))
    end)

    if ok and type(result) == "table" then
        roots = result
    else
        ok, result = pcall(function()
            local file = ESP_FOLDER .. "/assets.rbxm"

            writefile(file, raw)

            return game:GetObjects(getcustomasset(file))
        end)

        if ok and type(result) == "table" then
            roots = result
        end
    end

    if not roots then
        return
    end

    for _, root in ipairs(roots) do
        local particles = root.Name == "particles" and root or root:FindFirstChild("particles", true)

        if particles then
            getgenv().SleepyHitParticles = particles

            break
        end
    end

    for _, root in ipairs(roots) do
        local folder = root.Name == "effects" and root or root:FindFirstChild("effects", true)

        if folder then
            for _, kind in ipairs({"aura", "particle"}) do
                local group = folder:FindFirstChild(kind)

                if group then
                    for _, effect in ipairs(group:GetChildren()) do
                        esp.effects[kind][effect.Name] = effect
                    end
                end
            end

            break
        end
    end

    for _, record in pairs(esp.running) do
        pcall(esp_effects_refresh, record)
    end
end)

esp_refresh_tags()
esp_healthbar_options()
esp_chams_apply()

if esp_spectate then
    pcall(function()
        esp_spectate.DuelSubjectChanged:Connect(function()
            esp.bridge_event:Fire("subject")
        end)
    end)

    esp_set_subject(esp_spectate.CurrentDuelSubject)
end
